def investigate(context, acquire):
    history = acquire("history")
    goal = context.get("goal")
    actions = context.get("actions", [])

    def simulate(put_mode, trigger, channel_mode):
        items = {}
        log_count = 0
        main_total = 0
        other_total = 0
        main_changes = 0
        in_tx = False
        tx_snapshot = None
        tx_log_snapshot = 0
        tx_main_total_snapshot = 0
        tx_other_total_snapshot = 0
        tx_changes_snapshot = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                key = act.get("key")
                value = act.get("value")
                changed = 0
                inserted = False
                if key in items:
                    if put_mode == "ignore":
                        changed = 0
                    elif put_mode == "replace":
                        items[key] = value
                        changed = 1
                    else:
                        items[key] = value
                        changed = 1
                else:
                    items[key] = value
                    changed = 1
                    inserted = True
                if inserted and trigger:
                    log_count += 1
                if conn == "main":
                    main_total += changed
                    main_changes = changed
                else:
                    other_total += changed
            elif op == "update":
                key = act.get("key")
                value = act.get("value")
                changed = 0
                if key in items:
                    items[key] = value
                    changed = 1
                if conn == "main":
                    main_total += changed
                    main_changes = changed
                else:
                    other_total += changed
            elif op == "delete":
                key = act.get("key")
                changed = 0
                if key in items:
                    del items[key]
                    changed = 1
                if conn == "main":
                    main_total += changed
                    main_changes = changed
                else:
                    other_total += changed
            elif op == "begin":
                in_tx = True
                tx_snapshot = dict(items)
                tx_log_snapshot = log_count
                tx_main_total_snapshot = main_total
                tx_other_total_snapshot = other_total
                tx_changes_snapshot = main_changes
            elif op == "commit":
                in_tx = False
            elif op == "rollback":
                if tx_snapshot is not None:
                    items.clear()
                    items.update(tx_snapshot)
                    log_count = tx_log_snapshot
                    main_total = tx_main_total_snapshot
                    other_total = tx_other_total_snapshot
                    main_changes = tx_changes_snapshot
                in_tx = False

        if channel_mode == "changes":
            ch = main_changes
        elif channel_mode == "total_main":
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(items), sum(items.values())

    modes = ["ignore", "replace", "upsert"]
    triggers = [False, True]
    channels = ["changes", "total_main", "total_both"]

    valid = []
    for pm in modes:
        for tr in triggers:
            for cm in channels:
                ok = True
                for rec in history:
                    obs = rec.get("observed", {})
                    acts = rec.get("actions", [])
                    saved = actions
                    actions = acts
                    ch, cnt, sm = simulate(pm, tr, cm)
                    actions = saved
                    if ch != obs.get("channel") or cnt != obs.get("committed_count") or sm != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    valid.append((pm, tr, cm))

    if not valid:
        return {"value": None, "unresolved": True}

    results = set()
    for pm, tr, cm in valid:
        ch, cnt, sm = simulate(pm, tr, cm)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
